#include <stdlib.h>
#include <string.h>
#include <omp.h>
#include <immintrin.h>

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define VW 8
#define MR 6
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif
#define NR (2 * VW)
#define KCMAX 256
#define NCW 256
#define NCP (NCW / NR)

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof(v)); }

static float *g_Ap = NULL, *g_Bp = NULL;
static size_t g_acap = 0, g_bcap = 0;
static int *g_flags = NULL;
static size_t g_fcap = 0;

static void *grow(void *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) & ~(size_t)4095;
    p = aligned_alloc(4096, need);
    *cap = need;
    return p;
}

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#endif
}

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int accum)
{
#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VW);
#define FMA(i) { vf av = (vf){0} + a[i]; c##i##_0 += av * b0; c##i##_1 += av * b1; }
        ROWS(FMA)
#undef FMA
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (accum) {
#define STA(i) { float *r = c + (size_t)(i) * ldc; \
                 stu(r, ldu(r) + c##i##_0); stu(r + VW, ldu(r + VW) + c##i##_1); }
            ROWS(STA)
#undef STA
        } else {
#define STS(i) { float *r = c + (size_t)(i) * ldc; stu(r, c##i##_0); stu(r + VW, c##i##_1); }
            ROWS(STS)
#undef STS
        }
    } else {
#if defined(__AVX512F__)
        __mmask16 m0 = nr >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1);
        __mmask16 m1 = nr >= 32 ? (__mmask16)0xFFFF
                     : nr <= 16 ? (__mmask16)0 : (__mmask16)((1u << (nr - 16)) - 1);
#define STM(i) if ((i) < mr) { float *r = c + (size_t)(i) * ldc; \
            __m512 t0 = (__m512)c##i##_0, t1 = (__m512)c##i##_1; \
            if (accum) { t0 = _mm512_add_ps(t0, _mm512_maskz_loadu_ps(m0, r)); \
                         t1 = _mm512_add_ps(t1, _mm512_maskz_loadu_ps(m1, r + 16)); } \
            _mm512_mask_storeu_ps(r, m0, t0); _mm512_mask_storeu_ps(r + 16, m1, t1); }
        ROWS(STM)
#undef STM
#else
        float tmp[MR * NR] __attribute__((aligned(64)));
#define STT(i) { *(vf *)(tmp + (i) * NR) = c##i##_0; *(vf *)(tmp + (i) * NR + VW) = c##i##_1; }
        ROWS(STT)
#undef STT
        if (accum) {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] += tmp[i * NR + j];
        } else {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] = tmp[i * NR + j];
        }
#endif
    }
}

static void pack_a_panel(const float *A, float *dst, int r, int n)
{
    int row0 = r * MR;
    int mr = n - row0 < MR ? n - row0 : MR;
    const float *src = A + (size_t)row0 * n;
    if (mr == MR) {
        const float *s[MR];
        for (int i = 0; i < MR; i++) s[i] = src + (size_t)i * n;
        for (int k = 0; k < n; k++) {
            float *d = dst + (size_t)k * MR;
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++) d[i] = s[i][k];
        }
    } else {
        for (int k = 0; k < n; k++) {
            float *d = dst + (size_t)k * MR;
            int i = 0;
            for (; i < mr; i++) d[i] = src[(size_t)i * n + k];
            for (; i < MR; i++) d[i] = 0.0f;
        }
    }
}

static void pack_b_panel(const float *B, float *dst, int p, int n)
{
    int j0 = p * NR;
    int nr = n - j0 < NR ? n - j0 : NR;
    const float *src = B + j0;
    if (nr == NR) {
        for (int k = 0; k < n; k++)
            memcpy(dst + (size_t)k * NR, src + (size_t)k * n, NR * sizeof(float));
    } else {
        for (int k = 0; k < n; k++) {
            int j = 0;
            for (; j < nr; j++) dst[(size_t)k * NR + j] = src[(size_t)k * n + j];
            for (; j < NR; j++) dst[(size_t)k * NR + j] = 0.0f;
        }
    }
}

/* flag: 0 = not packed, 1 = being packed, 2 = ready */
static inline int try_claim(int *f)
{
    if (__atomic_load_n(f, __ATOMIC_ACQUIRE) != 0) return 0;
    int z = 0;
    return __atomic_compare_exchange_n(f, &z, 1, 0, __ATOMIC_ACQ_REL, __ATOMIC_RELAXED);
}

static inline void wait_ready(int *f)
{
    while (__atomic_load_n(f, __ATOMIC_ACQUIRE) != 2) cpu_relax();
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;

    g_Ap = (float *)grow(g_Ap, &g_acap, (size_t)mp * MR * n * sizeof(float));
    g_Bp = (float *)grow(g_Bp, &g_bcap, (size_t)np * NR * n * sizeof(float));
    g_flags = (int *)grow(g_flags, &g_fcap, (size_t)(mp + np) * sizeof(int));
    float *Ap = g_Ap, *Bp = g_Bp;
    int *af = g_flags, *bf = g_flags + mp;
    memset(g_flags, 0, (size_t)(mp + np) * sizeof(int));

    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;

    int nth = omp_get_max_threads();
    int ntn = (np + NCP - 1) / NCP;
    int mpt = (mp * ntn) / (4 * nth);
    if (mpt < 1) mpt = 1;
    if (mpt > 8) mpt = 8;
    int ntm = (mp + mpt - 1) / mpt;

    #pragma omp parallel proc_bind(close)
    {
        #pragma omp for schedule(dynamic, 1) collapse(2)
        for (int ti = 0; ti < ntm; ti++) {
            for (int tj = 0; tj < ntn; tj++) {
                int p0 = ti * mpt, p1 = p0 + mpt < mp ? p0 + mpt : mp;
                int q0 = tj * NCP, q1 = q0 + NCP < np ? q0 + NCP : np;

                /* lazily pack the panels this tile needs */
                for (int q = q0; q < q1; q++)
                    if (try_claim(&bf[q])) {
                        pack_b_panel(B, Bp + (size_t)q * n * NR, q, n);
                        __atomic_store_n(&bf[q], 2, __ATOMIC_RELEASE);
                    }
                for (int p = p0; p < p1; p++)
                    if (try_claim(&af[p])) {
                        pack_a_panel(A, Ap + (size_t)p * n * MR, p, n);
                        __atomic_store_n(&af[p], 2, __ATOMIC_RELEASE);
                    }
                for (int q = q0; q < q1; q++) wait_ready(&bf[q]);
                for (int p = p0; p < p1; p++) wait_ready(&af[p]);

                for (int pc = 0; pc < n; pc += kcb) {
                    int kc = n - pc < kcb ? n - pc : kcb;
                    int accum = pc > 0;
                    for (int p = p0; p < p1; p++) {
                        int i0 = p * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        const float *ap = Ap + (size_t)p * n * MR + (size_t)pc * MR;
                        float *crow = C + (size_t)i0 * n;
                        for (int q = q0; q < q1; q++) {
                            int j0 = q * NR;
                            int nr = n - j0 < NR ? n - j0 : NR;
                            const float *bp = Bp + (size_t)q * n * NR + (size_t)pc * NR;
                            kernel(kc, ap, bp, crow + j0, n, mr, nr, accum);
                        }
                    }
                }
            }
        }
    }
}
